import * as React from "react";
import * as BDTLL from "../../BDTLLCommon";
import "./analyzerPageStatus.css";

interface IAnalyzerPageStatusProps {
    id: string;
    url: string;
    threatStatus: BDTLL.PageStatus;
    linkScannerActive: boolean;
}

interface IAnalyzerPageStatusState {
    threatStatus?: BDTLL.PageStatus;
    linkScannerActive?: boolean;
    title: string;
    text: string;
    icon: BDTLL.StatusIcon;
}

type PageState = {
    [key in BDTLL.PageStatus]: IAnalyzerPageStatusState
}

const DefaultPageState : PageState = {
    [BDTLL.PageStatus.SAFE]: {
        title: BDTLL.Utils.getLocalizedText("title_safe"),
        text: BDTLL.Utils.getLocalizedText("popup_text_safe"),
        icon: BDTLL.StatusIcon.SAFE
    },
    [BDTLL.PageStatus.MALWARE]: {
        title: BDTLL.Utils.getLocalizedText("title_malware"),
        text: BDTLL.Utils.getLocalizedText("text_malware"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.PHISHING]: {
        title: BDTLL.Utils.getLocalizedText("title_phish"),
        text: BDTLL.Utils.getLocalizedText("text_phish"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.FRAUD]: {
        title: BDTLL.Utils.getLocalizedText("title_fraud"),
        text: BDTLL.Utils.getLocalizedText("text_fraud"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.MINER]: {
        title: BDTLL.Utils.getLocalizedText("title_miner"),
        text: BDTLL.Utils.getLocalizedText("text_miner"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.PUA]: {
        title: BDTLL.Utils.getLocalizedText("title_pua"),
        text: BDTLL.Utils.getLocalizedText("text_pua"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.MALVERTISING]: {
        title: BDTLL.Utils.getLocalizedText("title_malvertising"),
        text: BDTLL.Utils.getLocalizedText("text_malvertising"),
        icon: BDTLL.StatusIcon.CRITICAL
    },
    [BDTLL.PageStatus.SPAM]: {
        title: BDTLL.Utils.getLocalizedText("title_untrusted"),
        text: BDTLL.Utils.getLocalizedText("text_untrusted"),
        icon: BDTLL.StatusIcon.ALERT
    },
    [BDTLL.PageStatus.UNTRUSTED]: {
        title: BDTLL.Utils.getLocalizedText("title_untrusted"),
        text: BDTLL.Utils.getLocalizedText("text_untrusted"),
        icon: BDTLL.StatusIcon.ALERT
    },
    [BDTLL.PageStatus.WHITELISTED]: {
        title: BDTLL.Utils.getLocalizedText("title_whitelist"),
        text: BDTLL.Utils.getLocalizedText("text_whitelist_popup"),
        icon: BDTLL.StatusIcon.WHITELISTED
    },
    [BDTLL.PageStatus.SESSION_WHITELISTED]: {
        title: BDTLL.Utils.getLocalizedText("title_whitelist"),
        text: BDTLL.Utils.getLocalizedText("text_session_whitelist_popup"),
        icon: BDTLL.StatusIcon.WHITELISTED
    },
    [BDTLL.PageStatus.DISABLED]: {
        title: BDTLL.Utils.getLocalizedText("title_disabled_threat_filter"),
        text: BDTLL.Utils.getLocalizedText("text_disabled_threat_filter"),
        icon: BDTLL.StatusIcon.DISABLED,
    },
    [BDTLL.PageStatus.SEARCH_ANALYZER_DISABLED]: {
        title: BDTLL.Utils.getLocalizedText("title_disabled_search_analyzer"),
        text: BDTLL.Utils.getLocalizedText("text_disabled_search_analyzer"),
        icon: BDTLL.StatusIcon.DISABLED,
    }
}

export class AnalyzerPageStatus extends React.Component<IAnalyzerPageStatusProps, IAnalyzerPageStatusState> {
    constructor(props: IAnalyzerPageStatusProps) {
        super(props);
        this.state = this.getPageState(props.threatStatus, props.linkScannerActive);
        if (BDTLL.DEBUG_MODE) {
            console.log("Rendering Page Status...");
        }
    }

    shouldDisplaySearchDisabled(threatStatus: BDTLL.PageStatus, linkScannerActive: boolean): boolean {
        return threatStatus == BDTLL.PageStatus.SAFE &&
                !linkScannerActive &&
                BDTLL.Utils.getDomainForLinkScan(this.props.url) != null;
    }

    setPageState(threatStatus: BDTLL.PageStatus, linkScannerActive: boolean): void {
        this.setState(this.getPageState(threatStatus, linkScannerActive));
    }

    getPageState(threatStatus: BDTLL.PageStatus, linkScannerActive: boolean): IAnalyzerPageStatusState {
        let pageState: IAnalyzerPageStatusState;

        if (this.shouldDisplaySearchDisabled(threatStatus, linkScannerActive)) {
            pageState = { ...DefaultPageState[BDTLL.PageStatus.SEARCH_ANALYZER_DISABLED] };
        } else {
            pageState = { ...DefaultPageState[threatStatus] };
        }

        pageState.threatStatus = threatStatus;
        pageState.linkScannerActive = linkScannerActive;

        return pageState;
    }

    render(): React.JSX.Element {
        const iconClassName: string = "BDTLL_left_box " + this.state.icon;
        const titleTextArray: string[] = BDTLL.Utils.getLocalizedText("web_protection_title").split("[CompanyName]");
        const firstPartOfText: string = titleTextArray[0];
        const secondPartOfText: string = titleTextArray[1];

        return (
            <div id={this.props.id} className="BDTLL_Search_Popup">
                <div className={iconClassName}></div>
                <div className="BDTLL_right_box">
                    <p className="BDTLL_strong BDTLL_title">
                        <b>{this.state.title}</b>
                    </p>
                    <p className="BDTLL_mild BDTLL_description">{this.state.text}</p>
                    <p className="BDTLL_strong BDTLL_web_protection">
                        {firstPartOfText != "" ? <span className="BDTLL_before_company">{firstPartOfText}</span> : null}
                        <span className="BDTLL_company">
                            <b>{BDTLL.Consts.COMPANY_NAME} {BDTLL.Consts.PRODUCT_NAME}</b>
                        </span>
                        {secondPartOfText != "" ? <span className="BDTLL_after_company">{secondPartOfText}</span> : null}
                    </p>
                </div>
            </div>
        )
    }
}
