import * as React from "react";
import * as BDTLL from "../../BDTLLCommon";
import "./tooltip.css";

interface IStatusTooltipProps {
    url: string;
    threatStatus: BDTLL.PageStatus;
}

export class StatusTooltip extends React.Component<IStatusTooltipProps> {
    imgSrc: string;

    constructor(props: IStatusTooltipProps) {
        super(props);
        const icon: BDTLL.BarIcon = BDTLL.toBarIcon[props.threatStatus];
        this.imgSrc = BDTLL.Utils.getExtensionUrl(icon);
    }

    render(): React.JSX.Element {
        return (
            <img className="BDTLL_status" src={this.imgSrc}></img>
        );
    }
}
